function row(name,symbol,target,note,tail){const b=button('',()=>open(target),'fza-row');b.dataset.accountNav=target;const i=node('span','fza-row-icon');i.append(icon(symbol));const text=node('span','fza-row-copy');text.append(node('strong','',t(name)));if(note)text.append(node('small','',note));b.append(i,text);if(tail!==undefined)b.append(node('span','fza-row-tail',tail));b.append(icon('chevron'));return b;}
