function saved(){const entries=bridge.accountSaved();if(!entries.length){empty('saved','savedEmpty','savedHint');return;}body.append(node('p','fza-caption',t('device')));const list=node('div','fza-product-list');for(const item of [...entries].reverse()){const card=node('article','fza-product'),a=node('a','fza-product-link');a.href=validURL(item.url);a.target='_blank';a.rel='noopener noreferrer sponsored';a.setAttribute('aria-label',item.title||t('goStore'));const media=node('div','fza-product-image');media.append(icon('photo'));if(validURL(item.image)){const img=node('img');img.src=validURL(item.image);img.alt='';img.loading='lazy';img.referrerPolicy='no-referrer';img.addEventListener('error',()=>img.remove(),{once:true});img.addEventListener('load',()=>media.classList.add('loaded'),{once:true});media.append(img);}const info=node('div','fza-product-info');info.append(node('h3','',item.title||item.raw_title||item.store),node('p','',item.store||''),node('strong','',item.price||''));a.append(media,info);const remove=button('',()=>{try{bridge.accountRemoveSaved(item.url);render();}catch(_){toast(t('storageError'));}},'fza-round fza-remove');remove.append(icon('close'));remove.setAttribute('aria-label',t('remove')+' '+(item.title||''));card.append(a,remove);list.append(card);}body.append(list);}
function historyPage(){if(!history.length){empty('history','historyEmpty','historyHint');return;}const tools=node('div','fza-list-tools');tools.append(node('span','fza-caption',t('device')),button(t('clear'),()=>{const confirm=node('div','fza-confirm');confirm.append(node('p','',t('clearPrompt')),button(t('confirm'),()=>{if(write(historyKey,[])){history=[];render();}},'fza-danger'),button(t('cancel'),render,'fza-text'));tools.replaceWith(confirm);},'fza-text'));body.append(tools);const list=node('div','fza-group');for(const item of history){const line=node('div','fza-history-line'),b=button('',()=>{dialog.close();if(item.kind==='image')root.querySelector('[data-photo-btn]')?.click();else bridge.accountSearch(item.query,item.country);},'fza-history-search');b.append(icon(item.kind==='image'?'photo':'history'));const label=node('span');label.append(node('strong','',item.query||t('photo')),node('small','',new Intl.DateTimeFormat(root.dataset.lang||'en',{month:'short',day:'numeric'}).format(item.at)+' · '+(item.country||'')));b.append(label,icon('arrow'));b.setAttribute('aria-label',t(item.kind==='image'?'photoAgain':'again')+' '+item.query);const remove=button('',()=>{const updated=history.filter(x=>x.id!==item.id);if(write(historyKey,updated)){history=updated;render();}},'fza-round');remove.append(icon('close'));remove.setAttribute('aria-label',t('remove')+' '+item.query);line.append(b,remove);list.append(line);}body.append(list);}
function toggle(label,note,key,action){const row=node('label','fza-toggle-row'),copy=node('span');copy.append(node('strong','',t(label)),node('small','',t(note)));const input=node('input','fza-switch');input.type='checkbox';input.checked=!!prefs[key];input.setAttribute('role','switch');input.dataset.accountToggle=key;input.addEventListener('change',async()=>{const next=input.checked;if(action&&!await action(next)){input.checked=false;return;}const updated={...prefs,[key]:next};if(write(prefsKey,updated))prefs=updated;else input.checked=!next;});row.append(copy,input);return row;}
function settings(){body.append(block(row('notifications','bell','notifications'),row('details','user','profile')));const preferences=node('section','fza-group fza-preferences');preferences.append(node('h3','fza-section-title',t('market')));for(const [source,label] of [['[data-profile-market-select]','country'],['[data-profile-language-select]','language'],['[data-solar-mode]','appearance']]){const existing=root.querySelector(source);if(!existing)continue;const field=node('label','fza-field'),span=node('span','',label==='country'?(ar()?'السوق':'Market'):label==='language'?(ar()?'اللغة':'Language'):t('appearance')),select=node('select');for(const opt of existing.options)select.append(new Option(opt.textContent,opt.value));select.value=existing.value;select.dataset.accountPreference=label;select.addEventListener('change',()=>{existing.value=select.value;existing.dispatchEvent(new Event('change',{bubbles:true}));render();});field.append(span,select);preferences.append(field);}preferences.append(node('p','fza-caption',t('currencyNote')));body.append(preferences,block(toggle('historySetting','historySettingHint','history')));}
