function profile(){
 if(!member){heading(t('details'),t('signinDetails'));body.append(providerButtons());return;}
 const form=node('form','fza-group fza-contact');
 const nameField=node('label','fza-field'),nameInput=node('input');
 nameInput.type='text';nameInput.name='name';nameInput.autocomplete='name';nameInput.value=member.name||'';nameInput.dir='auto';nameInput.maxLength=100;nameInput.placeholder=t('namePlaceholder');nameInput.dataset.accountName='';
 const nameHint=node('small','fza-caption',t('nameHint'));nameHint.id=dialog.id+'-name-hint';nameInput.setAttribute('aria-describedby',nameHint.id);
 nameField.append(node('span','',t('name')),nameInput,nameHint);
 const email=node('label','fza-field'),address=node('input');
 address.type='text';address.value=member.email||t('noEmail');address.readOnly=true;address.dir='ltr';address.dataset.accountEmail='';
 const relay=member.provider==='apple'&&/^[^@\s]+@(?:privaterelay\.appleid\.com|private\.icloud\.com)$/i.test(member.email||'');
 const emailHint=node('small','fza-caption',t(relay?'appleEmailHint':'verified'));emailHint.id=dialog.id+'-email-hint';address.setAttribute('aria-describedby',emailHint.id);email.append(node('span','',t('email')),address,emailHint);
 const phone=node('label','fza-field'),number=node('input');
 number.type='tel';number.name='phone';number.autocomplete='tel';number.value=member.phone||'';number.dir='ltr';number.maxLength=24;number.placeholder='+965';number.dataset.accountPhone='';phone.append(node('span','',t('phone')),number,node('small','fza-caption',t('phoneHint')));
 const save=node('button','fza-primary',t('save'));save.type='submit';form.append(nameField,email,phone,save);
 const cleanName=value=>value.normalize('NFC').replace(/[\x00-\x1f\x7f-\x9f\u202a-\u202e\u2066-\u2069]/g,' ').replace(/\s+/g,' ').trim();
 form.addEventListener('submit',async e=>{
  e.preventDefault();if(save.disabled)return;
  const name=cleanName(nameInput.value),value=number.value.replace(/[\s()-]/g,'');
  if([...name].length>100||/[<>]/.test(name)){toast(t('nameInvalid'));nameInput.focus();return;}
  if(value&&!/^\+[1-9][0-9]{6,14}$/.test(value)){toast(t('phoneInvalid'));number.focus();return;}
  const accountID=member.id,access=session?.access_token,atRevision=revision,payload={phone:value};
  if(name!==(member.name||''))payload.name=name;
  save.disabled=true;nameInput.disabled=true;number.disabled=true;
  try{
   const data=await request('/profile',payload,access);
   if(session?.access_token!==access||member?.id!==accountID)return;
   if(!data.member||data.member.id!==accountID||('name'in payload&&data.member.name!==name))throw Error('profile_update_failed');
   member=data.member;
   if(form.isConnected){nameInput.value=member.name||'';number.value=member.phone||'';}
   else if(dialog.open&&view==='home')render();
   if(dialog.open&&revision===atRevision)toast(t('savedChanges'));
  }catch(e){
   if(session?.access_token===access&&member?.id===accountID&&dialog.open&&revision===atRevision)toast(t(e.code===401?'loginExpired':e.message==='invalid_name'?'nameInvalid':e.message==='invalid_phone'?'phoneInvalid':'error'));
  }finally{save.disabled=false;nameInput.disabled=false;number.disabled=false;}
 });
 body.append(form);
}
