async function request(path,payload,token=session?.access_token){if(!api)throw Error('unavailable');const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),8000);try{const headers={Accept:'application/json'};if(token)headers.Authorization='Bearer '+token;if(payload!==undefined)headers['Content-Type']='application/json';const res=await fetch(api+'/api/account'+path,{method:payload===undefined?'GET':'POST',headers,body:payload===undefined?undefined:JSON.stringify(payload),credentials:'omit',signal:ctl.signal});const data=await res.json();if(!res.ok||!data.ok){const e=Error(data.error||data.detail||'account');e.code=res.status;throw e;}return data;}finally{clearTimeout(timer);}}
async function loadConfig(){if(config&&!config.unavailable||configFlight)return configFlight;configFlight=(async()=>{try{config=await request('/config');}catch(_){config={providers:{},billing:{available:false},unavailable:true};}finally{configFlight=null;if(dialog.open&&(['home','signin'].includes(view)||(view==='profile'&&!member)))render();}})();return configFlight;}
function random(){const bytes=crypto.getRandomValues(new Uint8Array(32));return btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
async function hash(value){const bytes=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)));return btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
async function signIn(provider){if(busy)return;busy=true;render();try{await loadConfig();if(!config.providers?.[provider]){toast(t('loginUnavailable'));return;}await root.fzBilling?.beforeSignIn();const verifier=random()+random(),flow=random();sessionStorage.setItem(flowKey,JSON.stringify({verifier,flow,at:Date.now()}));const dest=new URL(location.href);dest.hash='';const data=await request('/auth/start',{provider,return_to:dest.href,challenge:await hash(verifier),flow});const url=new URL(data.authorize_url);if(url.protocol!=='https:'||url.origin!==(provider==='google'?'https://accounts.google.com':'https://appleid.apple.com'))throw Error('invalid_redirect');toast(t('loginBusy'));location.assign(url.href);}catch(_){toast(t('loginFailed'));}finally{busy=false;render();}}
async function resumeLogin(){const params=new URLSearchParams(location.hash.slice(1));if(params.has('findzia-auth-error')){window.history.replaceState(window.history.state,'',location.pathname+location.search);sessionStorage.removeItem(flowKey);open();toast(t('loginFailed'));return;}if(params.has('findzia-login')){window.history.replaceState(window.history.state,'',location.pathname+location.search);let flow;try{flow=JSON.parse(sessionStorage.getItem(flowKey));sessionStorage.removeItem(flowKey);}catch(_){}open();if(!flow||Date.now()-flow.at>600000||params.get('flow')!==flow.flow){toast(t('loginFailed'));return;}try{const data=await request('/auth/exchange',{code:params.get('findzia-login'),verifier:flow.verifier,flow:flow.flow},'');session={access_token:data.access_token,expires_at:data.expires_at};member=data.member;sessionStorage.setItem(sessionKey,JSON.stringify(session));render();}catch(_){session=null;member=null;toast(t('loginFailed'));}return;}if(session){try{member=(await request('/me')).member;render();}catch(e){if(e.code===401){session=null;member=null;sessionStorage.removeItem(sessionKey);}}}}
async function logout(){if(!member)return;const token=session?.access_token;member=null;session=null;root.dispatchEvent(new Event('fz:account-session'));try{sessionStorage.removeItem(sessionKey);}catch(_){}render();try{await request('/logout',{},token);}catch(_){}toast(t('logoutDone'));}
function record(data){if(seen.has(data.id))return;seen.add(data.id);if(seen.size>100)seen.delete(seen.values().next().value);counts();const kind=data.kind==='image'?'photo':'text';usage[kind]=(Number(usage[kind])||0)+1;write(usageKey,usage);const entry={id:Date.now().toString(36)+'-'+data.id,generation:data.id,query:String(data.query||'').slice(0,240),country:data.country||bridge.context().country,kind:data.kind,at:Date.now()};lastRecord=entry;if(prefs.history){history=[entry,...history.filter(x=>!(entry.query&&x.query===entry.query&&x.kind===entry.kind&&x.country===entry.country))].slice(0,60);write(historyKey,history);}if(dialog.open&&['home','usage','history'].includes(view))render();}
function done(id){if(!lastRecord||lastRecord.generation!==id)return;const c=bridge.context();const entry=lastRecord;lastRecord=null;if(prefs.history){const found=history.find(x=>x.id===entry.id);if(found){found.query=String(c.query||found.query||t('photo')).slice(0,240);write(historyKey,history);}}if(prefs.inApp)bridge.accountNotice(t('finished'));if(prefs.browser&&document.hidden&&'Notification'in window&&Notification.permission==='granted'){try{const n=new Notification('Findzia',{body:t('finished'),tag:'findzia-search-complete'});n.onclick=()=>{window.focus();n.close();};}catch(_){}}}
root.fzAccountRequest=record;root.fzAccountComplete=done;
const capture=e=>{const target=e.target.closest('[data-profile-settings],[data-dark-settings],[data-dark-saved]');if(!target||!root.contains(target))return;e.preventDefault();e.stopImmediatePropagation();root.querySelector('[data-dark-menu]')?.close();open(target.hasAttribute('data-dark-saved')?'saved':'home');};root.addEventListener('click',capture,true);
function labels(){buildMenu();root.querySelectorAll('[data-profile-settings],.fz-dark-header [data-dark-settings]').forEach(el=>{el.setAttribute('aria-label',t('account'));el.setAttribute('aria-controls',dialog.id);});dialog.dataset.theme=root.dataset.theme;}
function menuState(){const home=root.querySelector('[data-main-nav="search"]');if(home){if(root.dataset.homeState==='empty')home.setAttribute('aria-current','page');else home.removeAttribute('aria-current');}}
const mainMenu=root.querySelector('[data-dark-menu]');const menuObserver=mainMenu?new MutationObserver(()=>{root.querySelectorAll('[data-dark-menu-open],[data-results-menu-open]').forEach(button=>button.setAttribute('aria-expanded',String(mainMenu.open)));if(mainMenu.open){menuState();window.FindziaModalScroll?.lock(mainMenu);}else window.FindziaModalScroll?.unlock(mainMenu);}):null;menuObserver?.observe(mainMenu,{attributes:true,attributeFilter:['open']});
const observer=new MutationObserver(()=>{clearToast();labels();render();});observer.observe(root,{attributes:true,attributeFilter:['data-lang','data-theme']});labels();
dialog.addEventListener('close',()=>{if(dialog.open)return;menuNavigation=false;viewTrail=[];root.dispatchEvent(new Event('fz:account-closed'));window.FindziaModalScroll?.unlock(dialog);document.documentElement.classList.remove('fz-account-open');if(returnFocus?.isConnected&&!document.querySelector('dialog[open]'))returnFocus.focus({preventScroll:true});});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
const onStorage=e=>{if(e.key===historyKey){const value=read(historyKey,[]);if(Array.isArray(value))history=value.slice(0,60);}if(e.key===usageKey)usage=read(usageKey,{});if(e.key===prefsKey)prefs={...prefs,...read(prefsKey,{})};if(dialog.open)render();};window.addEventListener('storage',onStorage);
const cleanup=e=>{if(!e.target?.contains(root))return;closed=true;observer.disconnect();menuObserver?.disconnect();if(mainMenu)window.FindziaModalScroll?.unlock(mainMenu);root.removeEventListener('click',capture,true);window.removeEventListener('storage',onStorage);delete root.fzAccountRequest;delete root.fzAccountComplete;dialog.close();dialog.remove();clearTimeout(toastTimer);document.removeEventListener('shopify:section:unload',cleanup);};document.addEventListener('shopify:section:unload',cleanup);
root.fzAccount={session:()=>session,member:()=>member,open,close:()=>dialog.close(),render,expire:()=>{session=null;member=null;try{sessionStorage.removeItem(sessionKey);}catch(_){}render();}};
root.fzAccount.ready=resumeLogin();
